values
  ($t$Aeonium$t$, $t$Aeonium arboreum$t$, null, $t$<p>Succulenta arbustiva con fusti legnosi e rosette carnose lucide all'apice; si propaga facilmente per talea. Cresce attivamente in autunno-primavera e va in semi-riposo durante la calura estiva.</p>$t$, $j${"luce": "Pieno sole / molto luminoso", "acqua": "Scarsa", "terreno": "Molto drenante"}$j$::jsonb, ARRAY[$t$cresce in autunno-primavera, va in semi-riposo in estate (perdita di qualche foglia basale è normale)$t$, $t$teme il gelo intenso e prolungato$t$, $t$evitare ristagni idrici$t$, $t$si propaga facilmente per talea di fusto$t$], $j${"irrigazione": {"primavera": "ogni 10-14 giorni", "estate": "ogni 15-20 giorni, ridotta per il riposo estivo", "autunno": "ogni 10-14 giorni", "inverno": "ogni 20-25 giorni"}, "concimazione": {"primavera": "ogni 30 giorni, con concime leggero per succulente", "estate": "sospesa (riposo vegetativo)", "autunno": "ogni 30 giorni", "inverno": "sospesa"}, "potatura": {"primavera": "cimatura per favorire la ramificazione", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "2-7-7", "estate": null, "autunno": "2-7-7", "inverno": null}}$j$::jsonb, null, null),
  ($t$Agapanto$t$, $t$Agapanthus$t$, null, null, $j${"luce": "Pieno sole", "acqua": "", "terreno": "Ricco, fertile e soprattutto ben drenato"}$j$::jsonb, null, $j${"irrigazione": {"primavera": "ogni 3 giorni", "estate": "ogni 2 giorni", "autunno": "ogni 7 giorni", "inverno": ""}, "concimazione": {"primavera": "ogni 15 giorni", "estate": "ogni 15 giorni", "autunno": "", "inverno": ""}, "potatura": {"primavera": "Rimuovi le foglie danneggiate dal gelo", "estate": "Taglia gli steli fioriti", "autunno": "Pulisci le foglie secche o ingiallite", "inverno": "Nessuna potatura"}, "npk": {"primavera": "20-10-20", "estate": "10-20-30", "autunno": null, "inverno": null}}$j$::jsonb, null, null),
  ($t$Agave$t$, $t$Agave sp.$t$, null, $t$Giovane pollone identificato a luglio 2026 (probabile Agave americana). Rosetta di foglie carnose che da adulta sviluppa margini spinosi.$t$, $j${"luce": "Pieno sole / molto luminoso", "acqua": "Scarsa", "terreno": "Molto drenante, sabbioso"}$j$::jsonb, ARRAY[$t$Teme i ristagni idrici più di ogni altra cosa$t$, $t$Da adulta le foglie diventano spinose e appuntite: posizionarla lontano dal passaggio$t$, $t$In casa richiede la posizione più luminosa possibile, idealmente vicino a una finestra/terrazzo esposto a sud$t$], $j${"irrigazione": {"primavera": "ogni 12-15 giorni", "estate": "ogni 10-15 giorni, solo a terreno completamente asciutto", "autunno": "ogni 20-25 giorni", "inverno": "ogni 30-40 giorni, minima"}, "concimazione": {"primavera": "ogni 90 giorni, con concime per piante grasse/succulente", "estate": "ogni 30 giorni", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "rimozione foglie secche o danneggiate", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "2-7-7", "estate": "2-7-7", "autunno": null, "inverno": null}}$j$::jsonb, null, null),
