  ($t$Tradescantia$t$, $t$Tradescantia zebrina$t$, null, $t$Tappezzante da esterno a crescita rapida e spontanea, con fusti striscianti fucsia e foglie striate; si comporta da infestante una volta ambientata.$t$, $j${"luce": "Mezz'ombra o sole filtrato", "acqua": "Scarsa, si adatta alla pioggia naturale", "terreno": "Non esigente, tollera anche terreni poveri"}$j$::jsonb, ARRAY[$t$teme il gelo intenso (sotto 0°C la parte aerea può seccare, ma ricaccia in primavera se le radici sono protette)$t$, $t$crescita molto rapida e invasiva: monitorare e contenere l'espansione$t$, $t$si radica facilmente da ogni frammento di fusto a contatto col terreno$t$, $t$evitare ristagni idrici prolungati$t$], $j${"irrigazione": {"primavera": "nessuna, si adatta alla pioggia naturale", "estate": "ogni 12-15 giorni in assenza di pioggia prolungata", "autunno": "nessuna, si adatta alla pioggia naturale", "inverno": "nessuna"}, "concimazione": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "potatura": {"primavera": "taglio di contenimento per limitare l'espansione", "estate": "taglio di contenimento se necessario", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": null, "estate": null, "autunno": null, "inverno": null}}$j$::jsonb, null, null),
  ($t$Ulivo$t$, $t$Olea europaea$t$, null, $t$L'ulivo è un albero sempreverde e una latifoglie, la cui attività vegetativa è pressoché continua, con attenuazione nel periodo invernale. Ha crescita lenta ed è molto longevo: in condizioni climatiche favorevoli può diventare millenario e arrivare ad altezze di 15-20 metri.$t$, $j${"luce": "Pieno sole", "acqua": "Irrigazione moderata senza ristagni", "terreno": "Tollera terreni poveri e sassosi"}$j$::jsonb, ARRAY[$t$Evitare ristagni idrici: l'olivo è molto sensibile a marciumi radicali.$t$, $t$Le giovani piante possono soffrire gelate sotto -5°C.$t$, $t$In vaso richiede più acqua rispetto alla coltivazione in piena terra$t$, $t$Potature drastiche riducono la produzione per 1–2 anni.$t$, $t$Attenzione a: Mosca dell'olivo (Bactrocera oleae), Cocciniglia mezzo grano di pepe, Occhio di pavone (Spilocaea oleaginea), Rogna dell'olivo (Pseudomonas savastanoi)$t$], $j${"irrigazione": {"primavera": "Ogni 10-14 giorni", "estate": "Ogni 10-14 giorni", "autunno": "ogni 30 giorni, solo in caso di siccità prolungata", "inverno": "Sospesa"}, "concimazione": {"primavera": "ogni 90 giorni, concime organico o pellettato ricco in potassio", "estate": "ogni 60 giorni, facoltativa per piante in vaso o terreni molto poveri", "autunno": "ogni 90 giorni, se necessario", "inverno": "Sospesa"}, "potatura": {"primavera": "Potatura di formazione e pulizia dopo il rischio gelate; eliminare rami secchi o incrociati.", "estate": "Eventuale spuntatura leggera per contenere la chioma.", "autunno": "Sospesa", "inverno": "Solo rimozione rami danneggiati dal vento o dal gelo."}, "npk": {"primavera": "5-5-10", "estate": "5-5-10", "autunno": "5-5-10", "inverno": null}}$j$::jsonb, null, null),
  ($t$Uva di gatto$t$, $t$Muscari armeniacum$t$, null, $t$Bulbosa primaverile molto rustica, nota per le infiorescenze blu a grappolo simili a piccoli acini.$t$, $j${"luce": "Sole o mezz'ombra", "acqua": "Moderata in primavera, quasi nulla in estate", "terreno": "Ben drenato"}$j$::jsonb, ARRAY[$t$Non tagliare le foglie finché non ingialliscono$t$, $t$Evitare irrigazioni estive (riposo del bulbo)$t$, $t$Fioritura scarsa se piantato troppo in profondità$t$, $t$richiede terreno drenante (evitare ristagni)$t$, $t$non tagliare le foglie verdi dopo la fioritura$t$, $t$evitare irrigazioni estive (riposo vegetativo)$t$, $t$fioritura scarsa → bulbi troppo profondi o poca luce$t$, $t$si naturalizza facilmente e aumenta nel tempo$t$], $j${"irrigazione": {"primavera": "ogni 7-10 giorni durante la fioritura", "estate": "nessuna (bulbo in riposo)", "autunno": "ogni 10-14 giorni se il terreno è molto secco", "inverno": "ogni 20-25 giorni, solo se asciutto"}, "concimazione": {"primavera": "ogni 30 giorni, dopo la fioritura con concime per bulbose", "estate": "nessuna", "autunno": "ogni 30 giorni (facoltativo)", "inverno": "nessuna"}, "potatura": {"primavera": "taglio leggero", "estate": "taglio leggero", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "5-10-15", "estate": null, "autunno": "5-10-15", "inverno": null}}$j$::jsonb, null, null),
  ($t$Verbena$t$, $t$Verbena hybrida$t$, null, $t$Annuale o perenne con fioritura continua.$t$, $j${"luce": "Sole", "acqua": "Regolare", "terreno": "Fertile"}$j$::jsonb, ARRAY[$t$Sensibile a oidio$t$, $t$ama sole pieno$t$, $t$teme ristagni$t$, $t$fioritura continua$t$, $t$crescita rapida$t$], $j${"irrigazione": {"primavera": "ogni 5-7 giorni", "estate": "ogni 4-6 giorni", "autunno": "ogni 7-10 giorni", "inverno": "ogni 15-20 giorni"}, "concimazione": {"primavera": "ogni 2 settimane", "estate": "ogni 2 settimane", "autunno": "ogni 30 giorni", "inverno": "sospesa"}, "potatura": {"primavera": "taglio leggero", "estate": "taglio leggero", "autunno": "taglio post-fioritura", "inverno": "nessuna"}, "npk": {"primavera": "5-10-10", "estate": "5-10-10", "autunno": "5-10-10", "inverno": null}}$j$::jsonb, null, null),
  ($t$Violaciocca$t$, $t$Matthiola incana$t$, null, $t$Biennale o perenne con fiori profumati.$t$, $j${"luce": "Sole", "acqua": "Moderata", "terreno": "Fertile"}$j$::jsonb, ARRAY[$t$ama sole pieno$t$, $t$teme caldo eccessivo$t$, $t$fioritura profumata$t$, $t$evitare ristagni$t$], $j${"irrigazione": {"primavera": "ogni 7 giorni", "estate": "ogni 5-7 giorni", "autunno": "ogni 10 giorni", "inverno": "ogni 12-15 giorni"}, "concimazione": {"primavera": "ogni 2 settimane", "estate": "ogni 2 settimane", "autunno": "ogni 30 giorni", "inverno": "sospesa"}, "potatura": {"primavera": "taglio leggero", "estate": "taglio post-fioritura", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "5-10-10", "estate": "5-10-10", "autunno": "5-10-10", "inverno": null}}$j$::jsonb, null, null),
  ($t$Zinnia$t$, $t$Zinnia elegans$t$, null, $t$Annuale dai fiori grandi e colorati.$t$, $j${"luce": "Sole", "acqua": "Regolare", "terreno": "Fertile"}$j$::jsonb, ARRAY[$t$Sensibile all'oidio$t$, $t$ama sole pieno$t$, $t$teme ristagni idrici$t$, $t$fioritura molto abbondante se ben concimata$t$, $t$sensibile all’oidio in condizioni di umidità elevata$t$], $j${"irrigazione": {"primavera": "ogni 5-7 giorni se non piove", "estate": "ogni 3-5 giorni nei periodi caldi", "autunno": "ogni 7-10 giorni", "inverno": "nessuna (pianta annuale)"}, "concimazione": {"primavera": "ogni 30 giorni, con concime per fiorite", "estate": "ogni 3-4 settimane con concime leggero", "autunno": "sospesa", "inverno": "sospesa"}, "calcio": {"primavera": "", "estate": "", "autunno": "", "inverno": ""}, "potatura": {"primavera": "nessuna", "estate": "taglio leggero", "autunno": "taglio leggero", "inverno": "nessuna"}, "npk": {"primavera": "5-10-10", "estate": "5-10-10", "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": [], "finestra_trapianto": [], "resistenza_gelo": null, "spaziatura_cm": null, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $t$annuale$t$),
  ($t$Zinnia a foglia stretta$t$, $t$Zinnia angustifolia$t$, null, $t$<p>Specie diversa dalla comune Zinnia elegans: fiore singolo più aperto, con petali stretti e distanziati (non sovrapposti) e centro ispido/arruffato. Molto più rustica e resistente a siccità e oidio della Zinnia elegans. Spesso venduta come serie "Star" (es. Golden/Yellow Star).</p>$t$, $j${"luce": "Sole", "acqua": "Scarsa/moderata", "terreno": "Ben drenato, anche povero"}$j$::jsonb, ARRAY[$t$molto più resistente a siccità e oidio della Zinnia elegans comune$t$, $t$portamento compatto e ramificato, ottima da bordura$t$, $t$fioritura abbondante e continua$t$, $t$teme comunque i ristagni idrici$t$], $j${"irrigazione": {"primavera": "ogni 7-10 giorni se non piove", "estate": "ogni 5-7 giorni nei periodi caldi", "autunno": "ogni 10 giorni", "inverno": "nessuna (pianta annuale)"}, "concimazione": {"primavera": "ogni 30 giorni, con concime per fiorite", "estate": "ogni 3-4 settimane con concime leggero", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "taglio leggero", "autunno": "taglio leggero", "inverno": "nessuna"}, "npk": {"primavera": "5-10-10", "estate": "5-10-10", "autunno": null, "inverno": null}}$j$::jsonb, null, null),
  ($t$Zucca$t$, $t$Cucurbita moschata$t$, $t$Cucurbitaceae$t$, $t$Ortaggio annuale rampicante/strisciante a maturazione autunnale; la varietà Butternut ha polpa arancione dolce.$t$, $j${"luce": "Pieno sole", "acqua": "Abbondante durante la crescita", "terreno": "Fertile, ricco di sostanza organica"}$j$::jsonb, ARRAY[$t$Richiede molto spazio per svilupparsi (rampicante vigorosa)$t$, $t$teme il freddo: mettere a dimora solo dopo le ultime gelate$t$, $t$impollinazione manuale utile in assenza di insetti impollinatori$t$, $t$raccolta a fine estate/inizio autunno, quando la buccia si indurisce$t$], $j${"irrigazione": {"primavera": "ogni 3-4 giorni", "estate": "ogni 2-3 giorni", "autunno": "ogni 7 giorni", "inverno": ""}, "concimazione": {"primavera": "ogni 15 giorni", "estate": "ogni 10-15 giorni", "autunno": "", "inverno": ""}, "potatura": {"primavera": "nessuna", "estate": "eventuale cimatura per contenere lo sviluppo", "autunno": "", "inverno": ""}, "npk": {"primavera": "5-10-15", "estate": "5-10-15", "autunno": null, "inverno": null}, "calcio": {"primavera": "ogni 21 giorni", "estate": "ogni 21 giorni", "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Cucurbitaceae", "giorni_germinazione": "10-15", "giorni_trapianto": "20-25", "giorni_raccolta": "90-120", "finestra_semina": ["primavera"], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 150, "consociazioni_favorevoli": ["mais", "fagiolo"], "consociazioni_sfavorevoli": ["patata"]}$j$::jsonb, $t$annuale$t$),
  ($t$Zucchina$t$, $t$Cucurbita pepo$t$, $t$Cucurbitaceae$t$, $t$Ortaggio annuale da frutto, produzione abbondante per tutta l'estate.$t$, $j${"luce": "Pieno sole", "acqua": "Abbondante", "terreno": "Fertile, ben drenato"}$j$::jsonb, ARRAY[$t$Molto sensibile a oidio in estate avanzata$t$, $t$raccogliere i frutti giovani per stimolare nuova produzione$t$, $t$evitare di bagnare le foglie (favorisce le malattie fungine)$t$, $t$impollinazione manuale utile in assenza di insetti impollinatori$t$], $j${"irrigazione": {"primavera": "ogni 3-4 giorni", "estate": "ogni 2 giorni", "autunno": "ogni 7 giorni", "inverno": ""}, "concimazione": {"primavera": "ogni 15 giorni", "estate": "ogni 10-15 giorni", "autunno": "", "inverno": ""}, "potatura": {"primavera": "nessuna", "estate": "rimozione foglie basali ingiallite", "autunno": "", "inverno": ""}, "npk": {"primavera": "5-10-15", "estate": "5-10-15", "autunno": null, "inverno": null}, "calcio": {"primavera": "ogni 21 giorni", "estate": "ogni 21 giorni", "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Cucurbitaceae", "giorni_germinazione": "4-14", "giorni_trapianto": "15-20", "giorni_raccolta": "45-60", "finestra_semina": ["primavera"], "finestra_trapianto": ["primavera", "estate"], "resistenza_gelo": "nessuna", "spaziatura_cm": 90, "consociazioni_favorevoli": ["mais", "fagiolo", "basilico"], "consociazioni_sfavorevoli": ["patata"]}$j$::jsonb, $t$annuale$t$),
  ($t$ZZ Plant$t$, $t$Zamioculcas zamiifolia$t$, null, $t$<p>Pianta da interno estremamente resistente, con rizomi carnosi sotterranei che immagazzinano acqua e riserve, e foglie pinnate lucide verde scuro. Tollera molto bene la trascuratezza, la scarsa luce e le annaffiature saltuarie.</p>$t$, $j${"luce": "Tollera anche poca luce, cresce meglio con luce indiretta filtrata", "acqua": "Scarsa", "terreno": "Molto drenante"}$j$::jsonb, ARRAY[$t$teme moltissimo i ristagni idrici: il marciume dei rizomi è la causa di morte più comune$t$, $t$tollera bene ambienti poco luminosi, ideale per angoli bui della casa$t$, $t$crescita lenta, non necessita di rinvasi frequenti$t$, $t$pianta tossica se ingerita: tenere lontano da animali domestici e bambini$t$], $j${"irrigazione": {"primavera": "ogni 14-20 giorni", "estate": "ogni 10-14 giorni", "autunno": "ogni 20-25 giorni", "inverno": "ogni 30 giorni"}, "concimazione": {"primavera": "una volta al mese con concime leggero per piante verdi", "estate": "una volta al mese", "autunno": "sospesa", "inverno": "sospesa"}, "calcio": {"primavera": "", "estate": "", "autunno": "", "inverno": ""}, "potatura": {"primavera": "rimozione foglie ingiallite o danneggiate", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "20-10-10", "estate": "20-10-10", "autunno": null, "inverno": null}}$j$::jsonb, null, null);
